#!/usr/bin/env bash
set -euo pipefail

ROOT="TVRemote"
rm -rf "$ROOT"
mkdir -p "$ROOT"

cat > /tmp/tvremote_v3_payload.b64 <<'PAYLOAD'

PAYLOAD

base64 -d /tmp/tvremote_v3_payload.b64 > /tmp/tvremote_v3_payload.zip

python3 - <<'PY'
import zipfile
with zipfile.ZipFile("/tmp/tvremote_v3_payload.zip") as z:
    z.extractall("TVRemote")
print("TV Remote V3 project created.")
PY

rm -f /tmp/tvremote_v3_payload.b64 /tmp/tvremote_v3_payload.zip

echo
echo "=========================================="
echo " TV REMOTE V3 PROJECT CREATED"
echo "=========================================="
echo "Commit the TVRemote folder."
echo "Then GitHub Actions -> Build TV Remote V3 APKs -> Run workflow."
